const fs = require('fs');
const path = require('path');

const ELF32_MAGIC = 0x464c457f;
const ELFCLASS32 = 1;
const ELFDATA2LSB = 1;
const EM_MIPS = 8;

function parseELF(buf) {
  if (buf.readUInt32LE(0) !== ELF32_MAGIC) throw new Error('not an ELF');
  if (buf[4] !== ELFCLASS32) throw new Error('wrong class');
  if (buf[5] !== ELFDATA2LSB) throw new Error('wrong endian');
  const e_type = buf.readUInt16LE(16);
  const e_machine = buf.readUInt16LE(18);
  const e_entry = buf.readUInt32LE(24);
  const e_phoff = buf.readUInt32LE(28);
  const e_shoff = buf.readUInt32LE(32);
  const e_phentsize = buf.readUInt16LE(42);
  const e_phnum = buf.readUInt16LE(44);
  const e_shentsize = buf.readUInt16LE(46);
  const e_shnum = buf.readUInt16LE(48);
  const e_shstrndx = buf.readUInt16LE(50);
  if (e_machine !== EM_MIPS) throw new Error('wrong machine');
  const phdrs = [];
  for (let i = 0; i < e_phnum; i++) {
    const off = e_phoff + i * e_phentsize;
    const p_type = buf.readUInt32LE(off + 0);
    const p_offset = buf.readUInt32LE(off + 4);
    const p_vaddr = buf.readUInt32LE(off + 8);
    const p_paddr = buf.readUInt32LE(off + 12);
    const p_filesz = buf.readUInt32LE(off + 16);
    const p_memsz = buf.readUInt32LE(off + 20);
    const p_flags = buf.readUInt32LE(off + 24);
    const p_align = buf.readUInt32LE(off + 28);
    phdrs.push({p_type, p_offset, p_vaddr, p_filesz, p_memsz, p_flags, p_align});
  }
  return {e_entry, phdrs, e_phoff, e_phentsize, e_phnum, e_shoff, e_shentsize, e_shnum, e_shstrndx};
}

